    FOREIGN KEY (c1) REFERENCES t3(c1),
    FOREIGN KEY (c2) REFERENCES t2(c1)
);

counterexample:
INSERT INTO t1 (c1, c2) VALUES ('beer1', 'x');
INSERT INTO t1 (c1, c2) VALUES ('B', 'y');

INSERT INTO t2 (c1, c2) VALUES ('Amstel', 'x');
INSERT INTO t2 (c1, c2) VALUES ('Corona', 'y');

INSERT INTO t3 (c1, c2) VALUES ('u1', 'x');

-- t5 rows: one qualifies Q1 (Amstel, c3>2), one supports Q2's Corona membership but fails Q1 (c3<=2)
INSERT INTO t5 (c1, c2, c3) VALUES ('beer1', 'Amstel', 3.00);
INSERT INTO t5 (c1, c2, c3) VALUES ('B', 'Corona', 1.00);

-- t4 row tying t3.u1 to t1.B so Q2 can return 'u1'
INSERT INTO t4 (c1, c2, c3) VALUES ('u1', 'B', 5);

-- t6 row to satisfy c1 IN (t6 where c2 <> 'Corona') for 'u1'
INSERT INTO t6 (c1, c2) VALUES ('u1', 'Amstel');

